final _kPublicEndpoints = [
  // Add public routes here
];

final dioClientProvider = Provider<Dio>((ref) => _buildDioClient(ref));

// ─────────────────────────────────────────────────────────────────────────────
Dio _buildDioClient(Ref ref) {
  final storage = ref.watch(secureStorageProvider);

  final dio = Dio(
    BaseOptions(
      baseUrl: appFlavor == "prod" ? AppEnv.prodBaseUrl : AppEnv.devBaseUrl,
      connectTimeout: ApiConstants.connectTimeout,
      receiveTimeout: ApiConstants.receiveTimeout,
      headers: const {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
    ),
  );

  // Configure certificate verification
  _configureHttpClient(dio);

  dio
    ..interceptors.add(
      InterceptorsWrapper(
        onRequest: (options, handler) async {
          final isPublicEndpoint = _kPublicEndpoints.any(
            (endpoint) => options.path.contains(endpoint),
          );
          if (!isPublicEndpoint) {
            final token = await storage.read(key: 'token');
            if (token != null) {
              options.headers['Authorization'] = 'Bearer $token';
            }
          }
          handler.next(options);
        },
      ),
    )
    ..interceptors.add(
      RetryInterceptor(dio: dio, logPrint: (msg) => appLogger.d(msg)),
    )
    ..interceptors.add(
      LogInterceptor(
        requestBody: true,
        responseBody: true,
        logPrint: (msg) => appLogger.d(msg.toString()),
      ),
    );

  return dio;
}

// ─────────────────────────────────────────────────────────────────────────────
void _configureHttpClient(Dio dio) {
  dio.httpClientAdapter = IOHttpClientAdapter(
    createHttpClient: () {
      final client = HttpClient();
      if (kDebugMode) {
        client.badCertificateCallback = (cert, host, port) {
          appLogger.w(
            'Certificate verification skipped for $host (debug mode)',
          );
          return true;
        };
      }
      return client;
    },
  );
}



Future<T?> safeApiCall<T>({
    required Future<T> Function() apiCall,
    required FutureOr<T?> Function() onNoInternet,
    FutureOr<void> Function(AppException exception)? onError,
  }) async {
  // 1. Check current connectivity status
  final List<ConnectivityResult> connectivityResult = await (Connectivity().checkConnectivity());

  // connectivity_plus returns a list. If it contains 'none', there is no internet.
  if (connectivityResult.contains(ConnectivityResult.none)) {
    return await onNoInternet();
  }

  try {
    // 2. Internet is available, execute the API call
    return await apiCall();
  } on DioException catch (e) {
    final exception = AppException.fromDioError(e);
    await onError?.call(exception);
    return null;
  } catch (e, s) {
    final exception = AppException.fromError(e, s);
    await onError?.call(exception);
    return null;
  }
}

