class AppInput extends StatefulWidget {
  const AppInput({
    super.key,
    this.controller,
    required this.label,
    this.hint,
    this.maxLines = 1,
    this.hidePassword = false,
    this.typePassword = false,
    this.initialValue,
    this.keyboardType,
    this.textInputAction,
    this.readOnly = false,
    this.prefixIcon,
    this.suffixIcon,
    this.focusNode,
    this.autoFocus = false,
    this.required = false,
    this.onChanged,
  });

  final TextEditingController? controller;
  final String label;
  final String? hint;
  final int? maxLines;
  final bool hidePassword;
  final bool typePassword;
  final String? initialValue;
  final TextInputType? keyboardType;
  final TextInputAction? textInputAction;
  final bool readOnly;
  final Widget? prefixIcon;
  final Widget? suffixIcon;
  final FocusNode? focusNode;
  final bool autoFocus;
  final bool required;
  final Function(String c)? onChanged;

  @override
  State<AppInput> createState() => _AppInputState();

  InputType _getInputType() {
    if (keyboardType != null) {
      switch (keyboardType) {
        case TextInputType.emailAddress:
          return InputType.email;
        case TextInputType.number:
          return InputType.number;
        case TextInputType.phone:
          return InputType.phone;
        case TextInputType.url:
          return InputType.url;
        default:
          return InputType.text;
      }
    }
    if (typePassword) {
      return InputType.password;
    }
    return InputType.text;
  }
}

class _AppInputState extends State<AppInput> {
  @override
  void initState() {
    super.initState();
    if (widget.initialValue != null) {
      widget.controller?.text = widget.initialValue!;
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;

    return Column(
      spacing: AppConstants.space8,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        InputTitle(label: widget.label, required: widget.required),
        IgnorePointer(
          ignoring: widget.readOnly,
          child: TextFormField(
            validator: (value) {
              if (widget.required && (value == null || value.isEmpty)) {
                return 'This field is required';
              }
              if ((widget.keyboardType == TextInputType.emailAddress ||
                      widget.typePassword) &&
                  (value == null || value.isEmpty)) {
                return 'This field is required';
              }
              final result = ValidationService.validate(
                value ?? '',
                inputType: widget._getInputType(),
              );
              if (!result.isValid) {
                return result.error;
              }
              return null;
            },
            onChanged: widget.onChanged,
            focusNode: widget.focusNode,
            autofocus: widget.autoFocus,
            readOnly: widget.readOnly,
            controller: widget.controller,
            style: theme.textTheme.bodyMedium,
            initialValue: widget.controller == null
                ? widget.initialValue
                : null,
            maxLines: widget.maxLines,
            obscureText: widget.hidePassword,
            keyboardType: widget.keyboardType,
            textInputAction: widget.textInputAction,
            cursorColor: theme.colorScheme.primary,
            decoration: InputDecoration(
              hintText: widget.hint,
              prefixIcon: widget.prefixIcon,
              suffixIcon: widget.suffixIcon,
            ),
          ),
        ),
      ],
    );
  }
}

